import "@clayui/css/lib/css/atlas.css";
import "./DXCaseCard.scss";
import spritemap from "../icons/clay.svg";
import React from "react";
import Badge from 'react-bootstrap/Badge';
import ClayDropDown from "@clayui/drop-down";
import Button from 'react-bootstrap/Button';
import { ButtonProps, TagProps } from "../../utilities";


export interface CaseCardProps {
    title: string,
    subtitle: string,
    label: TagProps,
    options: ButtonProps[];
}

const DXCaseCard = ( props: CaseCardProps ) => {
    return (
        <div className="dxCaseCard">
            <div className="row">
                <div className="col-5">
                    <p className="dxCaseCard__title">{props.title}</p>
                </div>
                <div className="col-3">
                    <p>{props.subtitle}</p>
                </div>
                <div className="col-3">
                    <Badge
                        bg="" data-testid="case-card-label" className="dxCaseCard__label"
                        style={props.label.color ?
                            { color: props.label.color, borderColor: props.label.color } :
                            { color: "var(--primary-primary)", borderColor: "var(--primary-primary)" }}
                    >
                        {props.label.label}
                    </Badge>
                </div>
                <div className="col-1">
                    <div className="dxCaseCard__kebab">
                        <ClayDropDown
                            trigger={
                                <Button
                                    variant="unstyled"
                                    className="dxCaseCard__menuButton"
                                    aria-label="Dropdown menu"
                                >
                                    <svg className="dxCaseCard__menuIcon" viewBox="0 0 24 24">
                                        <use href={`${spritemap}#ellipsis-v`} />
                                    </svg>
                                </Button>
                            }
                            data-testid="case-card-options">
                            <ClayDropDown.ItemList>
                                {props.options.map( ( opt: ButtonProps, index: number ) => (
                                    <ClayDropDown.Item key={index} onClick={( e ) => opt.onClick( e )}>
                                        {opt.label}
                                    </ClayDropDown.Item>
                                ) )}
                            </ClayDropDown.ItemList>
                        </ClayDropDown>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DXCaseCard;
